1	// Package compact converts full.jsonl transcripts into a normalized,
2	// compact transcript.jsonl format. Only shared formatting is contained here.
3	package compact
4	
5	import (
6		"bufio"
7		"bytes"
8		"encoding/json"
9		"fmt"
10		"io"
11		"strings"
12	
13		"github.com/entireio/cli/cmd/entire/cli/textutil"
14		"github.com/entireio/cli/cmd/entire/cli/transcript"
15		"github.com/entireio/cli/redact"
16	)
17	
18	// MetadataFields provides metadata fields written to every output line.
19	type MetadataFields struct {
20		Agent      string // e.g. "claude-code"
21		CLIVersion string // e.g. "0.42.0"
22		StartLine  int    // checkpoint_transcript_start (0 = no truncation)
23	}
24	
25	// transcriptLine is the uniform output format for every line in transcript.jsonl.
26	// Field order is guaranteed by encoding/json (struct declaration order).
27	type transcriptLine struct {
28		V            int             `json:"v"`
29		Agent        string          `json:"agent"`
30		CLIVersion   string          `json:"cli_version"`
31		Type         string          `json:"type"`
32		TS           json.RawMessage `json:"ts,omitempty"`
33		ID           string          `json:"id,omitempty"`
34		InputTokens  int             `json:"input_tokens,omitempty"`
35		OutputTokens int             `json:"output_tokens,omitempty"`
36		Content      json.RawMessage `json:"content"`
37	}
38	
39	// newTranscriptLine returns a transcriptLine pre-filled with the shared
40	// metadata fields that are identical on every output line.
41	func newTranscriptLine(opts MetadataFields) transcriptLine {
42		return transcriptLine{
43			V:          1,
44			Agent:      opts.Agent,
45			CLIVersion: opts.CLIVersion,
46		}
47	}
48	
49	const toolResultStatusError = "error"
50	
51	// toolResultJSON is the compact result object inlined into tool_use blocks.
52	type toolResultJSON struct {
53		Output     string              `json:"output"`
54		Status     string              `json:"status"`
55		File       *toolResultFileJSON `json:"file,omitempty"`
56		MatchCount int                 `json:"matchCount,omitempty"`
57	}
58	
59	// toolResultFileJSON carries structured file metadata from Read/Edit tool results.
60	type toolResultFileJSON struct {
61		FilePath string `json:"filePath"`
62		NumLines int    `json:"numLines,omitempty"`
63	}
64	
65	// userTextBlock is a text block within user message content.
66	type userTextBlock struct {
67		ID   string `json:"id,omitempty"`
68		Text string `json:"text"`
69	}
70	
71	// Compact converts a full.jsonl transcript into the condensed transcript.jsonl format.
72	// The input must be pre-redacted (via redact.JSONLBytes or
73	// redact.AlreadyRedacted for trusted sources).
74	//
75	// The output format puts version, agent, and cli_version on every line,
76	// merges streaming assistant fragments with the same message ID, and inlines
77	// tool results into the preceding assistant's tool_use blocks:
78	//
79	//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user","ts":"...","content":"..."}
80	//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"assistant","ts":"...","id":"msg_xxx","content":[{"type":"text","text":"..."},{"type":"tool_use","id":"...","name":"...","input":{...},"result":{"output":"...","status":"..."}}]}
81	func Compact(redacted redact.RedactedBytes, opts MetadataFields) ([]byte, error) {
82		content := redacted.Bytes()
83	
84		// Formats that need detection on raw content before line truncation:
85		// - Single-object formats (OpenCode, Gemini): SliceFromLine would cut
86		//   a JSON object mid-value. They handle StartLine as a message-index offset.
87		// - Codex: session_meta header is only on the first line. Codex handles
88		//   StartLine as a response_item index offset.
89		if isOpenCodeFormat(content) {
90			return compactOpenCode(content, opts)
91		}
92	
93		if isGeminiFormat(content) {
94			return compactGemini(content, opts)
95		}
96	
97		// pi: detect on the raw header line. compactPi handles StartLine itself.
98		if isPiFormat(content) {
99			return compactPi(content, opts)
100		}
101	
102		if isCodexFormat(content) {
103			return compactCodex(content, opts)
104		}
105	
106		truncated := transcript.SliceFromLine(content, opts.StartLine)
107		if truncated == nil {
108			truncated = []byte{}
109		}
110	
111		if isCopilotFormat(truncated) {
112			return compactCopilot(truncated, opts)
113		}
114	
115		if isDroidFormat(truncated) {
116			return compactDroid(truncated, opts)
117		}
118	
119		return compactJSONL(truncated, opts)
120	}
121	
122	// droppedTypes are JSONL entry types that carry no parser-relevant data.
123	var droppedTypes = map[string]bool{
124		"progress":              true,
125		"file-history-snapshot": true,
126		"queue-operation":       true,
127		"system":                true,
128	}
129	
130	// userAliases maps JSONL type/role values to the canonical "user" kind.
131	// Covers Claude Code ("user", "human") and Cursor ("user" via "role" field).
132	var userAliases = map[string]bool{
133		transcript.TypeUser: true,
134		"human":             true,
135	}
136	
137	// normalizeKind returns the canonical entry kind ("user" or "assistant") for a
138	// JSONL transcript line. It checks the "type" field, then falls back to "role".
139	// Returns "" for unrecognised or dropped entries.
140	func normalizeKind(raw map[string]json.RawMessage) string {
141		kind := unquote(raw["type"])
142		if kind == "" {
143			kind = unquote(raw["role"])
144		}
145	
146		if droppedTypes[kind] {
147			return ""
148		}
149		if userAliases[kind] {
150			return transcript.TypeUser
151		}
152		if kind == transcript.TypeAssistant {
153			return transcript.TypeAssistant
154		}
155		return ""
156	}
157	
158	// linePreprocessor transforms a parsed JSONL line before conversion.
159	type linePreprocessor func(map[string]json.RawMessage) map[string]json.RawMessage
160	
161	// parsedEntry is an intermediate representation of a JSONL line used during
162	// the two-pass compact conversion.
163	type parsedEntry struct {
164		kind         string // "user" or "assistant"
165		ts           json.RawMessage
166		id           string            // message ID (assistant only)
167		userID       string            // prompt ID (user only, e.g. Claude's promptId)
168		inputTokens  int               // API input tokens (assistant only)
169		outputTokens int               // API output tokens (assistant only)
170		content      json.RawMessage   // stripped assistant content array, or nil
171		userText     string            // extracted user text
172		userImages   []json.RawMessage // image blocks from user messages
173		toolResults  []toolResultEntry // user tool_result entries
174	}
175	
176	// compactJSONL converts JSONL transcripts (Claude Code, Cursor) into the
177	// transcript.jsonl format.
178	func compactJSONL(content []byte, opts MetadataFields) ([]byte, error) {
179		return compactJSONLWith(content, opts, nil)
180	}
181	
182	func compactJSONLWith(content []byte, opts MetadataFields, preprocess linePreprocessor) ([]byte, error) {
183		base := newTranscriptLine(opts)
184	
185		// Pass 1: parse all lines into intermediate entries.
186		entries, err := parseJSONLEntries(content, preprocess)
187		if err != nil {
188			return nil, err
189		}
190	
191		// Pass 2: merge and emit.
192		var result []byte
193		for i := 0; i < len(entries); i++ {
194			e := entries[i]
195	
196			switch e.kind {
197			case transcript.TypeAssistant:
198				// Merge consecutive assistant entries with the same message ID.
199				merged := e
200				for i+1 < len(entries) && entries[i+1].kind == transcript.TypeAssistant && entries[i+1].id == e.id {
201					i++
202					merged = mergeAssistantEntries(merged, entries[i])
203				}
204	
205				// Look ahead for user tool_result entries to inline.
206				if i+1 < len(entries) && entries[i+1].kind == transcript.TypeUser && hasToolResults(entries[i+1]) {
207					userEntry := entries[i+1]
208					merged = inlineToolResults(merged, userEntry)
209					i++ // consume the user tool_result entry
210	
211					// If the consumed user entry also had text or image content, emit it
212					// as a separate user line after the assistant.
213					if userEntry.userText != "" || len(userEntry.userImages) > 0 {
214						emitAssistant(&result, base, merged)
215						emitUser(&result, base, userEntry)
216						continue
217					}
218				}
219	
220				if isEmptyContentArray(merged.content) {
221					continue
222				}
223	
224				emitAssistant(&result, base, merged)
225	
226			case transcript.TypeUser:
227				// User entries that are purely tool results were already consumed
228				// by the assistant look-ahead above. If we reach one here it was
229				// not preceded by an assistant with a matching tool_use, so emit
230				// it only if it has text or image content.
231				if hasToolResults(e) && e.userText == "" && len(e.userImages) == 0 {
232					continue
233				}
234				emitUser(&result, base, e)
235			}
236		}
237	
238		return result, nil
239	}
240	
241	func emitAssistant(result *[]byte, base transcriptLine, e parsedEntry) {
242		line := base
243		line.Type = transcript.TypeAssistant
244		line.TS = e.ts
245		line.ID = e.id
246		line.InputTokens = e.inputTokens
247		line.OutputTokens = e.outputTokens
248		line.Content = e.content
249		appendLine(result, line)
250	}
251	
252	func emitUser(result *[]byte, base transcriptLine, e parsedEntry) {
253		var blocks []json.RawMessage
254	
255		// Text block (with optional prompt ID).
256		if e.userText != "" || len(e.userImages) == 0 {
257			b, err := json.Marshal(userTextBlock{ID: e.userID, Text: e.userText})
258			if err != nil {
259				return
260			}
261			blocks = append(blocks, b)
262		}
263	
264		// Image blocks passed through verbatim.
265		blocks = append(blocks, e.userImages...)
266	
267		contentJSON, err := json.Marshal(blocks)
268		if err != nil {
269			return
270		}
271	
272		line := base
273		line.Type = transcript.TypeUser
274		line.TS = e.ts
275		line.Content = contentJSON
276		appendLine(result, line)
277	}
278	
279	// appendLine marshals a transcriptLine and appends it (with newline) to result.
280	func appendLine(result *[]byte, line transcriptLine) {
281		b, err := json.Marshal(line)
282		if err != nil {
283			return
284		}
285		*result = append(*result, b...)
286		*result = append(*result, '\n')
287	}
288	
289	// parseJSONLEntries parses all JSONL lines into intermediate entries,
290	// filtering dropped types and malformed lines.
291	func parseJSONLEntries(content []byte, preprocess linePreprocessor) ([]parsedEntry, error) {
292		reader := bufio.NewReader(bytes.NewReader(content))
293		var entries []parsedEntry
294	
295		for {
296			lineBytes, err := reader.ReadBytes('\n')
297			if err != nil && err != io.EOF {
298				return nil, fmt.Errorf("reading JSONL line: %w", err)
299			}
300	
301			if len(bytes.TrimSpace(lineBytes)) > 0 {
302				if e, ok := parseLine(lineBytes, preprocess); ok {
303					entries = append(entries, e)
304				}
305			}
306	
307			if err == io.EOF {
308				break
309			}
310		}
311	
312		return entries, nil
313	}
314	
315	// parseLine converts a single JSONL line into a parsedEntry.
316	// Returns ok=false for dropped/malformed lines.
317	func parseLine(lineBytes []byte, preprocess linePreprocessor) (parsedEntry, bool) {
318		var raw map[string]json.RawMessage
319		if err := json.Unmarshal(lineBytes, &raw); err != nil {
320			return parsedEntry{}, false
321		}
322	
323		if preprocess != nil {
324			raw = preprocess(raw)
325		}
326	
327		kind := normalizeKind(raw)
328		if kind == "" {
329			return parsedEntry{}, false
330		}
331	
332		e := parsedEntry{
333			kind: kind,
334			ts:   raw["timestamp"],
335		}
336	
337		msg := parseMessage(raw)
338	
339		switch kind {
340		case transcript.TypeAssistant:
341			if msg != nil {
342				e.id = unquote(msg["id"])
343				if contentRaw, ok := msg["content"]; ok {
344					e.content = stripAssistantContent(contentRaw)
345				}
346				e.inputTokens, e.outputTokens = extractUsageTokens(msg)
347			}
348	
349		case transcript.TypeUser:
350			e.userID = unquote(raw["promptId"])
351			if msg != nil {
352				if contentRaw, ok := msg["content"]; ok {
353					uc := extractUserContent(contentRaw)
354					e.userText = uc.text
355					e.userImages = uc.images
356					e.toolResults = uc.toolResults
357				}
358			}
359			// Enrich tool results with metadata from toolUseResult.
360			if turRaw, ok := raw["toolUseResult"]; ok {
361				var tur map[string]json.RawMessage
362				if json.Unmarshal(turRaw, &tur) == nil {
363					e.toolResults = enrichToolResults(e.toolResults, tur)
364				}
365			}
366		}
367	
368		return e, true
369	}
370	
371	// mergeAssistantEntries combines two assistant entries with the same message ID.
372	// Content arrays are concatenated; the later timestamp and token counts win
373	// (streaming fragments report cumulative usage, so the last fragment is final).
374	func mergeAssistantEntries(a, b parsedEntry) parsedEntry {
375		merged := a
376		merged.ts = b.ts
377		if b.inputTokens > 0 {
378			merged.inputTokens = b.inputTokens
379		}
380		if b.outputTokens > 0 {
381			merged.outputTokens = b.outputTokens
382		}
383	
384		var aBlocks, bBlocks []json.RawMessage
385		_ = json.Unmarshal(a.content, &aBlocks) //nolint:errcheck // best-effort merge
386		_ = json.Unmarshal(b.content, &bBlocks) //nolint:errcheck // best-effort merge
387		all := append(aBlocks, bBlocks...)      //nolint:gocritic // intentional append to new slice
388		if data, err := json.Marshal(all); err == nil {
389			merged.content = data
390		}
391	
392		return merged
393	}
394	
395	// inlineToolResults adds "result" fields to matching tool_use blocks in the
396	// assistant entry's content, using outputs from user tool_result entries.
397	func inlineToolResults(assistant, user parsedEntry) parsedEntry {
398		var blocks []map[string]json.RawMessage
399		if json.Unmarshal(assistant.content, &blocks) != nil || len(blocks) == 0 {
400			return assistant
401		}
402	
403		for _, tr := range user.toolResults {
404			// Find the tool_use block matching this tool_use_id.
405			idx := -1
406			for i := len(blocks) - 1; i >= 0; i-- {
407				if unquote(blocks[i]["type"]) == transcript.ContentTypeToolUse {
408					if tr.toolUseID == "" || unquote(blocks[i]["id"]) == tr.toolUseID {
409						idx = i
410						break
411					}
412				}
413			}
414			// No matching tool_use block: do not attach a result to unrelated content.
415			if idx == -1 {
416				continue
417			}
418	
419			blocks[idx]["result"] = buildToolResult(tr)
420		}
421	
422		if data, err := json.Marshal(blocks); err == nil {
423			assistant.content = data
424		}
425	
426		return assistant
427	}
428	
429	// buildToolResult constructs the compact result object for a tool_use block,
430	// including optional rich metadata (file, matchCount) when available.
431	func buildToolResult(tr toolResultEntry) json.RawMessage {
432		r := toolResultJSON{
433			Output:     tr.output,
434			Status:     "success",
435			MatchCount: tr.matchCount,
436		}
437		if tr.isError {
438			r.Status = toolResultStatusError
439		}
440		if tr.file != nil {
441			r.File = &toolResultFileJSON{
442				FilePath: tr.file.filePath,
443				NumLines: tr.file.numLines,
444			}
445		}
446		b, err := json.Marshal(r)
447		if err != nil {
448			return nil
449		}
450		return b
451	}
452	
453	// extractUsageTokens extracts input_tokens and output_tokens from a Claude
454	// message's "usage" object. Returns (0, 0) if usage is absent or malformed.
455	func extractUsageTokens(msg map[string]json.RawMessage) (inputTokens, outputTokens int) {
456		usageRaw, ok := msg["usage"]
457		if !ok {
458			return 0, 0
459		}
460		var usage struct {
461			InputTokens  int `json:"input_tokens"`
462			OutputTokens int `json:"output_tokens"`
463		}
464		if json.Unmarshal(usageRaw, &usage) != nil {
465			return 0, 0
466		}
467		return usage.InputTokens, usage.OutputTokens
468	}
469	
470	// isEmptyContentArray returns true if raw is a JSON empty array (`[]`).
471	func isEmptyContentArray(raw json.RawMessage) bool {
472		var arr []json.RawMessage
473		return json.Unmarshal(raw, &arr) == nil && len(arr) == 0
474	}
475	
476	func hasToolResults(e parsedEntry) bool {
477		return len(e.toolResults) > 0
478	}
479	
480	type toolResultEntry struct {
481		toolUseID string
482		output    string
483		isError   bool
484		// Rich metadata extracted from toolUseResult (optional).
485		file       *toolResultFile // Read/Edit: file path and line count
486		matchCount int             // Grep: number of matching files
487	}
488	
489	// toolResultFile carries structured file metadata from Read/Edit tool results.
490	type toolResultFile struct {
491		filePath string
492		numLines int // 0 if not available (e.g. Edit results)
493	}
494	
495	// enrichToolResults extracts structured metadata from a toolUseResult envelope
496	// and attaches it to the corresponding tool result entries.
497	//
498	// Claude Code's toolUseResult has different shapes per tool:
499	//   - Bash:  {stdout, stderr, interrupted, ...}
500	//   - Read:  {type:"text", file:{filePath, numLines, content, ...}}
501	//   - Grep:  {numFiles, numLines, filenames, content, mode}
502	//   - Edit:  {filePath, oldString, newString, structuredPatch, ...}
503	func enrichToolResults(results []toolResultEntry, tur map[string]json.RawMessage) []toolResultEntry {
504		// Bash-style: stdout provides the output text.
505		if stdout := unquote(tur["stdout"]); stdout != "" {
506			switch len(results) {
507			case 0:
508				// Keep compatibility with transcripts that only include toolUseResult.
509				results = append(results, toolResultEntry{output: stdout})
510			case 1:
511				results[0].output = stdout
512			}
513		}
514	
515		// Read-style: file object with filePath and numLines.
516		if fileRaw, ok := tur["file"]; ok {
517			var file struct {
518				FilePath string `json:"filePath"`
519				NumLines int    `json:"numLines"`
520			}
521			if json.Unmarshal(fileRaw, &file) == nil && file.FilePath != "" {
522				applyToSingleResult(results, func(tr *toolResultEntry) {
523					tr.file = &toolResultFile{filePath: file.FilePath, numLines: file.NumLines}
524				})
525			}
526		}
527	
528		// Edit-style: top-level filePath.
529		if filePath := unquote(tur["filePath"]); filePath != "" {
530			applyToSingleResult(results, func(tr *toolResultEntry) {
531				// Edit results don't have numLines.
532				tr.file = &toolResultFile{filePath: filePath}
533			})
534		}
535	
536		// Grep-style: numFiles as match count.
537		if numFilesRaw, ok := tur["numFiles"]; ok {
538			var n int
539			if json.Unmarshal(numFilesRaw, &n) == nil && n > 0 {
540				applyToSingleResult(results, func(tr *toolResultEntry) {
541					tr.matchCount = n
542				})
543			}
544		}
545	
546		return results
547	}
548	
549	// applyToSingleResult applies fn to the first (and expected only) tool result.
550	// toolUseResult is a single-tool envelope, so this is only meaningful when
551	// there's exactly one result entry.
552	func applyToSingleResult(results []toolResultEntry, fn func(*toolResultEntry)) {
553		if len(results) == 1 {
554			fn(&results[0])
555		}
556	}
557	
558	// parseMessage extracts and parses the "message" field from a JSONL transcript
559	// line. All JSONL agents nest content inside a "message" object.
560	func parseMessage(raw map[string]json.RawMessage) map[string]json.RawMessage {
561		msgRaw, ok := raw["message"]
562		if !ok {
563			return nil
564		}
565		var msg map[string]json.RawMessage
566		if json.Unmarshal(msgRaw, &msg) == nil {
567			return msg
568		}
569		return nil
570	}
571	
572	// userContent holds the extracted parts of a user message content array.
573	type userContent struct {
574		text        string
575		images      []json.RawMessage
576		toolResults []toolResultEntry
577	}
578	
579	// extractUserContent separates user message content into text, images, and tool_result entries.
580	// IDE context tags (e.g. <user_query>, <ide_opened_file>) are stripped from user text.
581	func extractUserContent(contentRaw json.RawMessage) userContent {
582		var str string
583		if json.Unmarshal(contentRaw, &str) == nil {
584			return userContent{text: textutil.StripIDEContextTags(str)}
585		}
586	
587		var blocks []json.RawMessage
588		if json.Unmarshal(contentRaw, &blocks) != nil {
589			return userContent{}
590		}
591	
592		var uc userContent
593	
594		for _, blockRaw := range blocks {
595			var block map[string]json.RawMessage
596			if json.Unmarshal(blockRaw, &block) != nil {
597				continue
598			}
599			blockType := unquote(block["type"])
600	
601			switch blockType {
602			case "tool_result":
603				var isErr bool
604				if raw, ok := block["is_error"]; ok {
605					_ = json.Unmarshal(raw, &isErr) //nolint:errcheck // best-effort
606				}
607				uc.toolResults = append(uc.toolResults, toolResultEntry{
608					toolUseID: unquote(block["tool_use_id"]),
609					output:    unquote(block["content"]),
610					isError:   isErr,
611				})
612	
613			case "image":
614				uc.images = append(uc.images, blockRaw)
615	
616			case transcript.ContentTypeText:
617				stripped := textutil.StripIDEContextTags(unquote(block[transcript.ContentTypeText]))
618				if stripped != "" {
619					uc.text += stripped + "\n\n"
620				}
621			}
622		}
623	
624		uc.text = strings.TrimSpace(uc.text)
625		return uc
626	}
627	
628	func stripAssistantContent(contentRaw json.RawMessage) json.RawMessage {
629		var str string
630		if json.Unmarshal(contentRaw, &str) == nil {
631			return contentRaw
632		}
633	
634		var blocks []map[string]json.RawMessage
635		if json.Unmarshal(contentRaw, &blocks) != nil {
636			return contentRaw
637		}
638	
639		result := make([]map[string]json.RawMessage, 0, len(blocks))
640		for _, block := range blocks {
641			blockType := unquote(block["type"])
642	
643			if blockType == "thinking" || blockType == "redacted_thinking" {
644				continue
645			}
646	
647			if blockType == transcript.ContentTypeToolUse {
648				stripped := make(map[string]json.RawMessage)
649				copyField(stripped, block, "type")
650				copyField(stripped, block, "id")
651				copyField(stripped, block, "name")
652				copyField(stripped, block, "input")
653				result = append(result, stripped)
654				continue
655			}
656	
657			result = append(result, block)
658		}
659	
660		b, err := json.Marshal(result)
661		if err != nil {
662			return contentRaw
