719	// writeTranscript writes the transcript and content hash to the checkpoint entries.
720	// Returns (true, nil) if files were written, (false, nil) if transcript was empty.
721	func (s *GitStore) writeTranscript(ctx context.Context, opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) (bool, error) {
722		logCtx := logging.WithComponent(ctx, "checkpoint")
723		transcriptBytes := opts.Transcript.Bytes()
724	
725		// TranscriptPath fallback: data read from disk is an untrusted source,
726		// so we redact it here. The in-memory path (opts.Transcript) is already
727		// pre-redacted by the caller — enforced by the RedactedBytes type.
728		if len(transcriptBytes) == 0 && opts.TranscriptPath != "" {
729			rawData, readErr := os.ReadFile(opts.TranscriptPath)
730			if readErr != nil {
731				// Non-fatal: transcript may not exist yet
732				rawData = nil
733			}
734			if len(rawData) > 0 {
735				redacted, redactErr := redact.JSONLBytes(rawData)
736				if redactErr != nil {
737					return false, fmt.Errorf("failed to redact transcript from file: %w", redactErr)
738				}
739				transcriptBytes = redacted.Bytes()
740			}
741		}
742		if len(transcriptBytes) == 0 {
743			return false, nil
744		}
745	
746		if opts.Agent == agent.AgentTypeCodex {
747			transcriptBytes = codex.SanitizePortableTranscript(transcriptBytes)
748		}
749	
750		// Chunk the transcript if it's too large
751		chunkStart := time.Now()
752		chunkCtx, chunkTranscriptSpan := perf.Start(ctx, "chunk_transcript")
753		chunks, err := agent.ChunkTranscript(chunkCtx, transcriptBytes, opts.Agent)
754		if err != nil {
755			chunkTranscriptSpan.RecordError(err)
756			chunkTranscriptSpan.End()
757			return false, fmt.Errorf("failed to chunk transcript: %w", err)
758		}
759		chunkTranscriptSpan.End()
760		chunkDuration := time.Since(chunkStart)
761	
762		// Write chunk files
763		blobStart := time.Now()
764		blobCtx, writeTranscriptBlobsSpan := perf.Start(chunkCtx, "write_transcript_blobs")
765		for i, chunk := range chunks {
766			chunkPath := basePath + agent.ChunkFileName(paths.TranscriptFileName, i)
767			blobHash, err := CreateBlobFromContent(s.repo, chunk)
768			if err != nil {
769				writeTranscriptBlobsSpan.RecordError(err)
770				writeTranscriptBlobsSpan.End()
771				return false, err
772			}
773			entries[chunkPath] = object.TreeEntry{
774				Name: chunkPath,
775				Mode: filemode.Regular,
776				Hash: blobHash,
777			}
778		}
779		writeTranscriptBlobsSpan.End()
780		blobDuration := time.Since(blobStart)
781	
782		// Content hash for deduplication (hash of full transcript)
783		contentHashStart := time.Now()
784		_, contentHashSpan := perf.Start(blobCtx, "write_transcript_content_hash")
785		contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcriptBytes))
786		hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
787		if err != nil {
788			contentHashSpan.RecordError(err)
789			contentHashSpan.End()
790			return false, err
791		}
792		entries[basePath+paths.ContentHashFileName] = object.TreeEntry{
793			Name: basePath + paths.ContentHashFileName,
794			Mode: filemode.Regular,
795			Hash: hashBlob,
796		}
797		contentHashSpan.End()
798	
799		logging.Debug(logCtx, "write transcript timings",
800			slog.String("session_id", opts.SessionID),
801			slog.String("checkpoint_id", opts.CheckpointID.String()),
802			slog.String("agent", string(opts.Agent)),
803			slog.Int64("chunk_transcript_ms", chunkDuration.Milliseconds()),
804			slog.Int64("write_transcript_blobs_ms", blobDuration.Milliseconds()),
805			slog.Int64("write_transcript_content_hash_ms", time.Since(contentHashStart).Milliseconds()),
806			slog.Int("transcript_bytes", len(transcriptBytes)),
807			slog.Int("chunk_count", len(chunks)),
808		)
809		return true, nil
810	}
