21	function normalizeStoredTranscriptSessions(
22	  value: unknown,
23	): Record<string, StoredTranscriptSession> | null {
24	  if (typeof value !== "object" || value === null || Array.isArray(value)) {
25	    return null
26	  }
27	
28	  const out: Record<string, StoredTranscriptSession> = {}
29	  for (const [key, entry] of Object.entries(value)) {
30	    if (typeof entry === "string") {
31	      out[key] = { content: entry }
32	      continue
33	    }
34	
35	    if (typeof entry !== "object" || entry === null || Array.isArray(entry)) {
36	      continue
37	    }
38	
39	    const session = entry as Record<string, unknown>
40	    if (typeof session.content !== "string") {
41	      continue
42	    }
43	
44	    const path = typeof session.path === "string" ? session.path : undefined
45	    const filename =
46	      typeof session.filename === "string" ? session.filename : filenameFromPath(path)
47	
48	    out[key] = {
49	      content: session.content,
50	      ref: typeof session.ref === "string" ? session.ref : undefined,
51	      path,
52	      filename,
53	    }
54	  }
55	
