// replaceCompactTranscript regenerates transcript.jsonl from the new full
// transcript, scoped at the checkpoint's transcript start (read from the
// session metadata already in entries). The compact transcript cannot reuse
// precomputed blobs: each checkpoint in a turn shares the full transcript but
// has its own start offset, so the compact content differs per checkpoint.
// Best-effort: on generation failure the previous transcript.jsonl entry (if
// any) is left in place so the metadata.json transcript pointer never dangles.
func (s *GitStore) replaceCompactTranscript(ctx context.Context, transcriptBytes []byte, agentType types.AgentType, sessionPath string, entries map[string]object.TreeEntry) {
	startLine := 0
	if entry, ok := entries[sessionPath+paths.MetadataFileName]; ok {
		if meta, err := s.readMetadataFromBlob(entry.Hash); err == nil {
			startLine = meta.GetTranscriptStart()
			if agentType == "" {
				agentType = meta.Agent
			}
		}
	}
	s.writeCompactTranscript(ctx, agentType, startLine, transcriptBytes, sessionPath, entries)
}

