// readCheckpointSummary reads and parses the root metadata.json for a checkpoint.
func readCheckpointSummary(t *testing.T, store *GitStore, cpID id.CheckpointID) CheckpointSummary {
	t.Helper()
	content, ok := readBranchFile(t, store, cpID.Path()+"/"+paths.MetadataFileName)
	if !ok {
		t.Fatalf("root metadata.json not found for checkpoint %s", cpID)
	}
	var summary CheckpointSummary
	if err := json.Unmarshal([]byte(content), &summary); err != nil {
		t.Fatalf("failed to parse checkpoint summary: %v", err)
	}
	return summary
}

